  7	static void SystemClock_Config(void);
  8	static void DrawLogo(uint32_t x0, uint32_t y0);
  9	
 10	int main(void)
 11	{
 12	  /* 1. Khoi tao HAL */
 13	  HAL_Init();
 14	
 15	  /* 2. Cau hinh xung nhip he thong */
 16	  SystemClock_Config();
 17	
 18	  /* 3. Khoi tao man hinh LCD */
 19	  if (BSP_LCD_Init() != LCD_OK)
 20	  {
 21	    while (1)
 22	    {
 23	      HAL_Delay(100);
 24	    }
 25	  }
 26	
 27	  /* 4. Khoi tao layer mac dinh tai vung nho SDRAM */
 28	  BSP_LCD_LayerDefaultInit(LTDC_ACTIVE_LAYER_BACKGROUND, LCD_FB_START_ADDRESS);
 29	  BSP_LCD_SelectLayer(LTDC_ACTIVE_LAYER_BACKGROUND);
 30	
 31	  /* 5. Bat hien thi man hinh */
 32	  BSP_LCD_DisplayOn();
 33	
 34	  /* 5b. Thong chuoi DSI va dua panel ra khoi reset */
 35	  __HAL_RCC_GPIOH_CLK_ENABLE();
 36	  GPIO_InitTypeDef gpio_xres = {0};
 37	  gpio_xres.Pin = GPIO_PIN_7;
 38	  gpio_xres.Mode = GPIO_MODE_OUTPUT_PP;
 39	  gpio_xres.Pull = GPIO_PULLUP;
 40	  gpio_xres.Speed = GPIO_SPEED_HIGH;
 41	  HAL_GPIO_Init(GPIOH, &gpio_xres);
 42	  HAL_GPIO_WritePin(GPIOH, GPIO_PIN_7, GPIO_PIN_SET);
 43	
 44	  /* Xoa SHTDN (bit 3) va bat DSIEN (bit 0) tren DSI Wrapper */
 45	  DSI->WCR &= ~DSI_WCR_SHTDN;
 46	  DSI->WCR |= DSI_WCR_DSIEN;
 47	
 48	  /* 6. Xoa man hinh ve mau trang */
 49	  BSP_LCD_Clear(LCD_COLOR_WHITE);
 50	
 51	  uint32_t lcd_w = BSP_LCD_GetXSize();
 52	
 53	  /* 7. Ve Logo PTIT (240x240) ra giua man hinh */
 54	  uint32_t logo_x = (lcd_w > LOGO_PTIT_WIDTH) ? ((lcd_w - LOGO_PTIT_WIDTH) / 2) : 0;
 55	  uint32_t logo_y = 30;
 56	  DrawLogo(logo_x, logo_y);
 57	
 58	  /* 8. Hien thi 4 dong chu thong tin theo yeu cau */
 59	  BSP_LCD_SetBackColor(LCD_COLOR_WHITE);
 60	  BSP_LCD_SetTextColor(LCD_COLOR_DARKBLUE);
 61	  BSP_LCD_SetFont(&Font20);
 62	
 63	  /* Dong 1: EIDE v3 — IDE nhung co tac tu dong tac gia */
 64	  BSP_LCD_DisplayStringAt(0, 290, (uint8_t *)"EIDE v3 - IDE nhung co tac tu dong tac gia", CENTER_MODE);
 65	
 66	  BSP_LCD_SetTextColor(LCD_COLOR_BLACK);
 67	  BSP_LCD_SetFont(&Font16);
 68	
 69	  /* Dong 2: Hoc vien: Vu Tri Cong */
 70	  BSP_LCD_DisplayStringAt(0, 330, (uint8_t *)"Hoc vien: Vu Tri Cong", CENTER_MODE);
 71	
 72	  /* Dong 3: Giang vien huong dan: TS. Nguyen Trung Hieu */
 73	  BSP_LCD_DisplayStringAt(0, 360, (uint8_t *)"Giang vien huong dan: TS. Nguyen Trung Hieu", CENTER_MODE);
 74	
 75	  BSP_LCD_SetTextColor(LCD_COLOR_RED);
 76	  /* Dong 4: Hoc vien Cong nghe Buu chinh Vien thong */
 77	  BSP_LCD_DisplayStringAt(0, 400, (uint8_t *)"Hoc vien Cong nghe Buu chinh Vien thong", CENTER_MODE);
 78	
 79	  while (1)
 80	  {
 81	    HAL_Delay(1000);
 82	  }
 83	}
