 85	static void DrawLogo(uint32_t x0, uint32_t y0)
 86	{
 87	  for (uint32_t y = 0; y < LOGO_PTIT_HEIGHT; y++)
 88	  {
 89	    for (uint32_t x = 0; x < LOGO_PTIT_WIDTH; x++)
 90	    {
 91	      uint32_t pixel = logo_ptit_data[y * LOGO_PTIT_WIDTH + x];
 92	      uint8_t a = (pixel >> 24) & 0xFF;
 93	      if (a > 0)
 94	      {
 95	        if (a == 255)
 96	        {
 97	          BSP_LCD_DrawPixel(x0 + x, y0 + y, pixel);
 98	        }
 99	        else
100	        {
101	          uint32_t r = (pixel >> 16) & 0xFF;
102	          uint32_t g = (pixel >> 8) & 0xFF;
103	          uint32_t b = pixel & 0xFF;
104	          r = (r * a + 255 * (255 - a)) / 255;
105	          g = (g * a + 255 * (255 - a)) / 255;
106	          b = (b * a + 255 * (255 - a)) / 255;
107	          BSP_LCD_DrawPixel(x0 + x, y0 + y, 0xFF000000UL | (r << 16) | (g << 8) | b);
108	        }
109	      }
110	    }
111	  }
112	}
