114	static void SystemClock_Config(void)
115	{
116	  RCC_ClkInitTypeDef RCC_ClkInitStruct;
117	  RCC_OscInitTypeDef RCC_OscInitStruct;
118	
119	  __HAL_RCC_PWR_CLK_ENABLE();
120	  __HAL_PWR_VOLTAGESCALING_CONFIG(PWR_REGULATOR_VOLTAGE_SCALE1);

280	    VBP  = NT35510_480X800_VBP;
281	    VFP  = NT35510_480X800_VFP;
282	    HSA  = NT35510_480X800_HSYNC;
283	    HBP  = NT35510_480X800_HBP;
284	    HFP  = NT35510_480X800_HFP;
285	  }
286	  else
287	  {
288	    VSA  = OTM8009A_480X800_VSYNC;
289	    VBP  = OTM8009A_480X800_VBP;
290	    VFP  = OTM8009A_480X800_VFP;
291	    HSA  = OTM8009A_480X800_HSYNC;
292	    HBP  = OTM8009A_480X800_HBP;
293	    HFP  = OTM8009A_480X800_HFP;
294	  }
295	
296	  hdsivideo_handle.VirtualChannelID = LCD_Driver_ID;
297	  hdsivideo_handle.ColorCoding = LCD_DSI_PIXEL_DATA_FMT_RBG888;
298	  hdsivideo_handle.VSPolarity = DSI_VSYNC_ACTIVE_HIGH;
299	  hdsivideo_handle.HSPolarity = DSI_HSYNC_ACTIVE_HIGH;
300	  hdsivideo_handle.DEPolarity = DSI_DATA_ENABLE_ACTIVE_HIGH;  
301	  hdsivideo_handle.Mode = DSI_VID_MODE_BURST; /* Mode Video burst ie : one LgP per line */
302	  hdsivideo_handle.NullPacketSize = 0xFFF;
303	  hdsivideo_handle.NumberOfChunks = 0;
304	  hdsivideo_handle.PacketSize                = HACT; /* Value depending on display orientation choice portrait/landscape */ 
305	  hdsivideo_handle.HorizontalSyncActive      = (HSA * laneByteClk_kHz) / LcdClock;
306	  hdsivideo_handle.HorizontalBackPorch       = (HBP * laneByteClk_kHz) / LcdClock;
307	  hdsivideo_handle.HorizontalLine            = ((HACT + HSA + HBP + HFP) * laneByteClk_kHz) / LcdClock; /* Value depending on display orientation choice portrait/landscape */
308	  hdsivideo_handle.VerticalSyncActive        = VSA;
309	  hdsivideo_handle.VerticalBackPorch         = VBP;
310	  hdsivideo_handle.VerticalFrontPorch        = VFP;
311	  hdsivideo_handle.VerticalActive            = VACT; /* Value depending on display orientation choice portrait/landscape */
312	  
313	  /* Enable or disable sending LP command while streaming is active in video mode */
314	  hdsivideo_handle.LPCommandEnable = DSI_LP_COMMAND_ENABLE; /* Enable sending commands in mode LP (Low Power) */
315	  
316	  /* Largest packet size possible to transmit in LP mode in VSA, VBP, VFP regions */
317	  /* Only useful when sending LP packets is allowed while streaming is active in video mode */
318	  hdsivideo_handle.LPLargestPacketSize = 16;
319	  
320	  /* Largest packet size possible to transmit in LP mode in HFP region during VACT period */
321	  /* Only useful when sending LP packets is allowed while streaming is active in video mode */
322	  hdsivideo_handle.LPVACTLargestPacketSize = 0;
323	  
324	  
325	  /* Specify for each region of the video frame, if the transmission of command in LP mode is allowed in this region */
326	  /* while streaming is active in video mode                                                                         */
327	  hdsivideo_handle.LPHorizontalFrontPorchEnable = DSI_LP_HFP_ENABLE;   /* Allow sending LP commands during HFP period */
328	  hdsivideo_handle.LPHorizontalBackPorchEnable  = DSI_LP_HBP_ENABLE;   /* Allow sending LP commands during HBP period */
329	  hdsivideo_handle.LPVerticalActiveEnable = DSI_LP_VACT_ENABLE;  /* Allow sending LP commands during VACT period */
330	  hdsivideo_handle.LPVerticalFrontPorchEnable = DSI_LP_VFP_ENABLE;   /* Allow sending LP commands during VFP period */
331	  hdsivideo_handle.LPVerticalBackPorchEnable = DSI_LP_VBP_ENABLE;   /* Allow sending LP commands during VBP period */
332	  hdsivideo_handle.LPVerticalSyncActiveEnable = DSI_LP_VSYNC_ENABLE; /* Allow sending LP commands during VSync = VSA period */
333	  
334	  /* Configure DSI Video mode timings with settings set above */
335	  HAL_DSI_ConfigVideoMode(&(hdsi_eval), &(hdsivideo_handle));
336	
337	  /* Configure DSI PHY HS2LP and LP2HS timings */
338	  PhyTimings.ClockLaneHS2LPTime = 35;
339	  PhyTimings.ClockLaneLP2HSTime = 35;

380	  /* Get LTDC Configuration from DSI Configuration */
381	  HAL_LTDCEx_StructInitFromVideoConfig(&(hltdc_eval), &(hdsivideo_handle));
382	  
383	  /* Initialize the LTDC */  
384	  HAL_LTDC_Init(&hltdc_eval);
385	
386	  /* Enable the DSI host and wrapper after the LTDC initialization
387	     To avoid any synchronization issue, the DSI shall be started after enabling the LTDC */
388	  HAL_DSI_Start(&(hdsi_eval));
389	  
390	#if !defined(DATA_IN_ExtSDRAM)
391	  /* Initialize the SDRAM */
392	  BSP_SDRAM_Init();
393	#endif /* DATA_IN_ExtSDRAM */
394	  
395	  /* Initialize the font */
396	  BSP_LCD_SetFont(&LCD_DEFAULT_FONT);
397	  /************************End LTDC Initialization*******************************/
398	
399	  /* Checking the ID to determine the type of component */
400	  if (Lcd_Driver_Type == LCD_CTRL_NT35510)
401	  {
402	    /***********************NT35510 Initialization********************************/  
403	    /* Initialize the NT35510 LCD Display IC Driver (TechShine LCD IC Driver)
404	    * depending on configuration set in 'hdsivideo_handle'.
405	    */
406	    NT35510_Init(NT35510_FORMAT_RGB888, orientation);
407	    /***********************End NT35510 Initialization****************************/
408	  }
409	  else if (Lcd_Driver_Type == LCD_CTRL_OTM8009A)
410	  {
411	    /***********************OTM8009A Initialization********************************/  
412	    /* Initialize the OTM8009A LCD Display IC Driver (KoD LCD IC Driver)
413	    *  depending on configuration set in 'hdsivideo_handle'.
414	    */
415	    OTM8009A_Init(OTM8009A_FORMAT_RGB888, orientation);
416	    /***********************End OTM8009A Initialization****************************/ 
417	  }
418	  else
419	  {
420	    return LCD_ERROR;
421	  }
422	
423	  /* Dam bao Wrapper DSI bat, SHTDN tat, PH7 cao */
424	  DSI->WCR &= ~DSI_WCR_SHTDN;
425	  DSI->WCR |= DSI_WCR_DSIEN;
426	  __HAL_DSI_WRAPPER_ENABLE(&hdsi_eval);
427	  HAL_GPIO_WritePin(GPIOH, GPIO_PIN_7, GPIO_PIN_SET);
428	
429	  return LCD_OK;
430	}
